import {categories} from './questions.js';
const app=document.querySelector('#app');let category=null,round=[],index=0,score=0,answered=false,view='home';
const letters=['A','B','C','D'];
function show(html){app.innerHTML=html;window.scrollTo(0,0);const h=app.querySelector('h1,h2');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function home(){view='home';show(`<section class="hero"><div><div class="eyebrow">EN LITEN PAUSE. LITT MER PEILING.</div><h1>Gi hjernen din<br>litt <span class="highlight">konfetti.</span></h1><p>Verden er full av artige ting å vite.<br>Velg et tema, og se hva du kan!</p><span class="mini">✦ GRATIS HJERNETRIM · INGEN TIDSPRESS</span></div><div class="mascot" aria-hidden="true"><span class="spark">✧</span><div class="blob"><span class="face">•ᴗ•</span></div><span class="speech">Klar for et lite aha?</span></div></section><section><div class="sectionhead"><div><h2>Hva er du nysgjerrig på?</h2><p>Finn din favoritt. Eller prøv noe helt nytt.</p></div><span class="mini">03 KATEGORIER Å UTFORSKE</span></div><div class="cards">${categories.map(c=>`<button class="card" data-category="${c.id}" style="--tint:${c.color}"><span class="icon" aria-hidden="true">${c.icon}</span><h3>${c.name}</h3><p>${c.description}</p><span class="tag">10 SPØRSMÅL · NYBEGYNNER</span><span class="arrow" aria-hidden="true">↗</span></button>`).join('')}</div></section><aside class="soon"><span style="font-size:30px" aria-hidden="true">🚀</span><div><h3>Mer krutt på vei</h3><p>Nye temaer, høyere nivåer og vennedueller.</p></div><span class="pill">KOMMER SENERE</span></aside>`);app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=categories.find(c=>c.id===b.dataset.category);levels();});}
function levels(){view='levels';show(`<div class="panel"><button class="back" id="back">← Alle kategorier</button><div class="icon" style="--tint:${category.color}" aria-hidden="true">${category.icon}</div><div class="eyebrow">VELG UTFORDRING</div><h1 style="font-size:44px">${category.name}</h1><p>Alle store aha-opplevelser starter et sted.</p><div class="levels"><button class="level" id="start"><div><h3>01 · Nybegynner</h3><span>10 spørsmål · Ingen tidspress</span></div><span aria-hidden="true">→</span></button><button class="level" disabled><div><h3>02 · Viderekommen</h3><span>Kommer i en senere versjon</span></div><span aria-hidden="true">🔒</span></button><button class="level" disabled><div><h3>03 · Ekspert</h3><span>Kommer i en senere versjon</span></div><span aria-hidden="true">🔒</span></button></div><p class="mini">FØRSTE SMAKEBIT · M1</p></div>`);document.querySelector('#back').onclick=home;document.querySelector('#start').onclick=start;}
function start(){round=[...category.questions];for(let i=round.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[round[i],round[j]]=[round[j],round[i]];}index=0;score=0;view='quiz';question();}
function question(){answered=false;const q=round[index];show(`<section class="panel"><button class="back" id="quit">← Avslutt runden</button><div class="quizmeta"><span>${category.icon} ${category.name}</span><span>${score} poeng</span></div><div class="progress" role="progressbar" aria-label="Spørsmål fullført" aria-valuemin="0" aria-valuemax="10" aria-valuenow="${index}"><div style="width:${index*10}%"></div></div><div class="eyebrow">SPØRSMÅL ${index+1} AV 10</div><h2 class="question">${q[0]}</h2><div class="answers">${q[1].map((a,i)=>`<button class="answer" data-answer="${i}"><span class="letter">${letters[i]}</span>${a}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div></section>`);document.querySelector('#quit').onclick=()=>document.querySelector('#quitDialog').showModal();app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));}
function answer(chosen){if(answered)return;answered=true;const q=round[index],right=chosen===q[2];if(right)score+=100;document.querySelector('.quizmeta span:last-child').textContent=score+' poeng';app.querySelectorAll('[data-answer]').forEach(b=>{const n=Number(b.dataset.answer);b.disabled=true;if(n===q[2])b.classList.add('correct');else if(n===chosen)b.classList.add('wrong');});document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${right?'✦ Helt riktig! +100 poeng':`Godt forsøk! Riktig svar: ${q[1][q[2]]}.`}</strong><p>${q[3]}</p><button class="primary" id="next">${index===9?'Se resultatet':'Neste spørsmål'} →</button></div>`;document.querySelector('#next').onclick=()=>{index++;index===10?result():question();};document.querySelector('#next').focus({preventScroll:true});}
function result(){view='result';show(`<section class="panel results"><div class="medal" aria-hidden="true">${score>=700?'🏆':'🎉'}</div><div class="eyebrow" style="justify-content:center">RUNDE FULLFØRT</div><h1 style="font-size:46px">${score>=700?'Du har skikkelig quizkrutt!':'Et lite aha rikere!'}</h1><div class="score">${score}<span style="font-size:20px"> / 1000</span></div><p>Du svarte riktig på <strong>${score/100} av 10</strong> spørsmål i ${category.name}.</p><p>${score>=700?'Dette lover godt for neste utfordring!':'Nysgjerrighet er den beste starten. Prøv en runde til!'}<br>Høyere nivåer kommer i en senere versjon.</p><div class="actions"><button class="primary" id="again">Spill igjen ↻</button><button class="secondary" id="home">Velg kategori</button></div></section>`);document.querySelector('#again').onclick=start;document.querySelector('#home').onclick=home;}
document.body.insertAdjacentHTML('beforeend','<dialog id="quitDialog"><h2>Ta en pause?</h2><p>Hvis du avslutter, mister du poengene i denne runden.</p><div class="actions"><button class="primary" id="keep">Fortsett runden</button><button class="secondary" id="leave">Avslutt</button></div></dialog>');
document.querySelector('#keep').onclick=()=>document.querySelector('#quitDialog').close();document.querySelector('#leave').onclick=()=>{document.querySelector('#quitDialog').close();home();};document.querySelector('#brand').onclick=e=>{e.preventDefault();view==='quiz'?document.querySelector('#quitDialog').showModal():home();};document.querySelector('#help').onclick=()=>document.querySelector('#info').showModal();document.querySelector('#closeInfo').onclick=()=>document.querySelector('#info').close();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{document.querySelector('#offline').textContent='Appen er klargjort for bruk uten nett. Åpne den én gang på nett etter installasjon.';}).catch(()=>{document.querySelector('#offline').textContent='Bruk uten nett kunne ikke klargjøres. Prøv igjen når du har nett.';});home();
